    await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "nope" })).rejects.toThrow();
    expect((await orgRepo.findOrgById(t.org.id))!.archivedAt).toBeNull();
    expect((await subscriptionRepo.findSubscription(t.org.id))!.status).toBe("trialing");
    await close(t);
    const err = await close(t).catch((e) => e);
    expect(err).toBeInstanceOf(AlreadyArchivedError);
    expect(toAppError(err).code).toBe("conflict");
    await expect(orgService.assertNotAlreadyClosed(t.userIds.owner, t.org.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(orgService.assertNotAlreadyClosed(t.userIds.member, t.org.id)).resolves.toBeUndefined();
  });

  it("refuses invitations, old or new, and does not notify", async () => {
    const t = await createTenant("close-invite");
    const token = randomToken(32);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "late@x.test", role: "member", expiresInDays: 14 }, t.userIds.owner, hashToken(token));
    const user = await userRepo.insertUser({ email: "late@x.test", name: "Late", passwordHash: "x" });
    await close(t);
    await expect(invitationService.acceptInvitation(user.id, { token })).rejects.toThrow();
    expect(await memberRepo.findMember(t.org.id, user.id)).toBeNull();
    const notes = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.owner, limit: 50, cursor: null } as never);
    expect(notes.items.filter((n) => n.kind === "member_joined")).toHaveLength(0);
  });

  it("sends no overdue reminders; subscription ends; no trial plan change; queued webhooks dropped; reindex skipped", async () => {
    resetOverdueTracking();
    const t = await createTenant("close-jobs");
    const other = await createTenant("close-jobs-other");
    await usageRepo.recomputeUsage(t.org.id);
    await usageRepo.recomputeUsage(other.org.id);
    for (const ten of [t, other]) {
      const n = await issueRepo.nextIssueNumber(ten.org.id, ten.project.id);
      await issueRepo.insertIssue(issueInput(ten.org.id, ten.project.id, { dueAt: "2026-01-01T00:00:00.000Z", assigneeId: ten.userIds.member }), ten.userIds.owner, n);
    }
    const endpoint = await webhookRepo.insertEndpoint({ orgId: t.org.id, url: "https://x.test/h", eventTypes: ["billing.plan_changed", "issue.created"] } as never, "secret");
    await webhookRepo.enqueueDelivery(t.org.id, endpoint.id, "issue.created", "{}");

    await close(t);
    const sub = (await subscriptionRepo.findSubscription(t.org.id))!;
    expect(sub.status).toBe("canceled");
    expect(sub.cancelAt).not.toBeNull();

    const seen: string[] = [];
    const off = subscribe("issue.overdue", (p) => { seen.push(p.orgId); });
    await runOverdueIssueJob(new Date());
    off();
    expect(seen).toEqual([other.org.id]);
    const notes = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.member, limit: 50, cursor: null } as never);
    expect(notes.items).toHaveLength(0);

    const res = await runWebhookDeliveryJob(new Date());
    const rows = getDb().select().from(webhookDeliveries).where(eq(webhookDeliveries.orgId, t.org.id)).all();
    expect(rows.every((r) => r.status !== "delivered")).toBe(true);
    expect(res.processed).toBe(0);

    const changed: string[] = [];
    const off2 = subscribe("billing.plan_changed", (p) => { changed.push(p.orgId); });
    await runTrialExpiryJob(new Date(Date.now() + 30 * 86400000));
    off2();
    expect(changed).not.toContain(t.org.id);
    expect(changed).toContain(other.org.id);
    const act = await activityRepo.listActivity({ orgId: t.org.id, limit: 100, cursor: null } as never);
    expect(act.items.filter((e) => e.action === "billing.plan_changed")).toHaveLength(0);
    expect((await subscriptionRepo.findSubscription(t.org.id))!.status).toBe("canceled");

    const before = getDb().select().from(searchIndex).where(eq(searchIndex.orgId, t.org.id)).all().length;
    const r = await runSearchReindexJob(t.org.id);
    expect(r.processed).toBe(0);
    expect(getDb().select().from(searchIndex).where(eq(searchIndex.orgId, t.org.id)).all().length).toBe(before);
    expect((await runSearchReindexJob(other.org.id)).processed).toBeGreaterThan(0);

    expect(await usageRepo.listOrgIdsForRollup(100)).not.toContain(t.org.id);
    expect(await usageRepo.listOrgIdsForRollup(100)).toContain(other.org.id);
    await runUsageRollupJob(new Date());
  });

